func:
// Remember which source IP each moteId last sent from, so commands
// (e.g. SET_PERIOD) can be routed back to the correct physical/simulated node
// instead of a single hardcoded address.
if (msg.ip && msg.payload && typeof msg.payload.moteId !== 'undefined') {
    flow.set('node_ip_' + msg.payload.moteId, msg.ip);
}
return msg;

// Per-mote dead-man's-switch: (re)start a timer every time this mote is
// heard from, sized to a margin over its own configured period T -- not a
// fixed window -- so a legitimately slow mote (period > old fixed 10s)
// doesn't get falsely flagged as crashed.
const moteId = msg.payload && msg.payload.moteId;
if (typeof moteId === 'undefined') { return null; }

const timers = context.get('timers') || {};
if (timers[moteId]) {
    clearTimeout(timers[moteId]);
}

const periodT = flow.get('period_' + moteId) || 5; // matches DEFAULT_PERIOD
const marginMs = (periodT * 3 + 5) * 1000;

timers[moteId] = setTimeout(() => {
    node.send({ payload: { moteId: moteId } });
}, marginMs);
context.set('timers', timers);

return null;

msg.url = "http://localhost:8080/traffic"; 
msg.payload = { 
    moteId: msg.payload.moteId 
};
return msg;

msg.url = "http://localhost:8080/parent";
msg.payload = {
    moteId: msg.payload.moteId,
    newParentId: msg.payload.newParentId
};
return msg;

msg.url = "http://localhost:8080/crash";
msg.payload = { 
    moteId: msg.payload.moteId 
};
return msg;

// ModeActor -> Node-RED: UDP to Contiki + HTTP response to Akka
const body = msg.payload || {};
const moteId = body.moteId;
const newT = (typeof body.newT !== 'undefined') ? body.newT
    : (typeof body.periodT !== 'undefined') ? body.periodT
        : (typeof body.newTStr !== 'undefined') ? parseInt(body.newTStr, 10)
            : undefined;

if (typeof newT === 'undefined' || Number.isNaN(Number(newT))) {
    node.warn("Missing or invalid newT/periodT in payload: " + JSON.stringify(body));
    const errMsg = RED.util.cloneMessage(msg);
    errMsg.payload = { error: "missing newT/periodT" };
    errMsg.statusCode = 400;
    return [null, errMsg];
}

// Output 1: UDP — JSON string (Contiki does json.loads on the packet)
// Routed to the mote's last-seen source IP (set by the IP Tracker node), so the
// command reaches the specific mote instead of a single fixed address.
const trackedIp = flow.get('node_ip_' + moteId);
if (!trackedIp) {
    node.warn("No tracked IP for mote " + moteId + " yet — falling back to localhost");
}
flow.set('period_' + moteId, Number(newT));

const udpMsg = RED.util.cloneMessage(msg);
udpMsg.ip = trackedIp || 'localhost';
udpMsg.payload = JSON.stringify({
    action: "SET_PERIOD",
    value: Number(newT),
    moteId: moteId
});

// Output 2: HTTP response — clone keeps req/res (fixes "No response object")
const resp = RED.util.cloneMessage(msg);
resp.payload = { status: "ok" };
resp.statusCode = 200;

return [udpMsg, resp];

// Node-RED owns crash -> physical revive coordination (symmetric
// recovery), independent of any callback from Akka: it already knows a
// mote crashed (the watchdog is what reported it), so after a fixed
// recovery delay it tells the physical/simulated mote to resume, then
// confirms the recovery back to Akka so the twin/dashboard can reflect it.
const moteId = msg.payload && msg.payload.moteId;
if (typeof moteId === 'undefined') { return [null, null]; }

const trackedIp = flow.get('node_ip_' + moteId);
if (!trackedIp) {
    node.warn('No tracked IP for mote ' + moteId + ' yet — revive will fall back to localhost');
}
const udpMsg = RED.util.cloneMessage(msg);
udpMsg.ip = trackedIp || 'localhost';
udpMsg.payload = JSON.stringify({ action: 'REVIVE', moteId: moteId });

const revivedMsg = RED.util.cloneMessage(msg);
revivedMsg.url = 'http://localhost:8080/revived';
revivedMsg.payload = { moteId: moteId };

return [udpMsg, revivedMsg];
